const languageCode = (language: Language) => language === "te" ? "te-IN" : language === "hi" ? "hi-IN" : "en-IN";

function Panel({ children, className = "" }: { children: ReactNode; className?: string }) {
  return <section className={`rounded-md border border-border bg-card ${className}`}>{children}</section>;
}

function Field({ label, value, onChange, type = "text", placeholder, required = false, min, max }: { label: string; value: string | number; onChange: (value: string) => void; type?: string; placeholder?: string; required?: boolean; min?: string | number; max?: string | number }) {
  const id = `field-${label.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
  return <label htmlFor={id} className="block space-y-1.5 text-sm font-medium text-foreground">{label}<input id={id} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm font-normal outline-none transition focus-visible:ring-2 focus-visible:ring-ring" type={type} value={value} placeholder={placeholder} required={required} min={min} max={max} onChange={(event) => onChange(event.target.value)} /></label>;
}

function SelectField({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: string[] }) {
  const id = `select-${label.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
  return <label htmlFor={id} className="block space-y-1.5 text-sm font-medium text-foreground">{label}<select id={id} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm font-normal outline-none focus-visible:ring-2 focus-visible:ring-ring" value={value} onChange={(event) => onChange(event.target.value)}>{options.map((option) => <option key={option}>{option}</option>)}</select></label>;
}

function PageHeading({ eyebrow, title, detail, action }: { eyebrow?: string; title: string; detail?: string; action?: ReactNode }) {
  return <div className="mb-6 flex flex-wrap items-end justify-between gap-4"><div>{eyebrow && <p className="mb-1 text-xs font-semibold uppercase tracking-wide text-leaf">{eyebrow}</p>}<h1 className="font-display text-3xl leading-tight text-foreground">{title}</h1>{detail && <p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{detail}</p>}</div>{action}</div>;
}

function CropImage({ crop, className = "" }: { crop: Crop; className?: string }) {
  const photo = cropPhotos[crop.id];
  return photo ? <img src={photo.url} alt={photo.alt} className={`h-full w-full object-cover ${className}`} loading="lazy" /> : <div className={`flex h-full w-full items-center justify-center bg-leaf/15 text-leaf ${className}`}><Leaf aria-hidden="true" /></div>;
}

function CropCard({ crop, onAdd, onOpen, added }: { crop: Crop; onAdd: (crop: Crop) => void; onOpen: (crop: Crop) => void; added?: boolean }) {
  return <article className="overflow-hidden rounded-md border border-border bg-card"><button type="button" onClick={() => onOpen(crop)} className="block aspect-[4/3] w-full overflow-hidden text-left" aria-label={`Open ${crop.name} guide`}><CropImage crop={crop} className="transition duration-300 hover:scale-[1.03]" /></button><div className="space-y-3 p-4"><div className="flex items-start justify-between gap-2"><div><p className="text-xs text-muted-foreground">{crop.category}</p><h3 className="mt-1 font-display text-xl">{crop.name}</h3></div><span className="rounded-sm bg-sun/25 px-2 py-1 text-xs text-foreground">~{crop.harvestDays} days</span></div><p className="line-clamp-2 text-sm leading-5 text-muted-foreground">{crop.summary}</p><div className="flex items-center justify-between gap-2"><span className="text-xs text-muted-foreground">{crop.minSunHours}+ hrs · {crop.difficulty}</span><Button size="sm" variant={added ? "secondary" : "default"} onClick={() => onAdd(crop)} disabled={added}>{added ? <Check /> : <Plus />}{added ? "In garden" : "Add"}</Button></div></div></article>;
}

